import{_ as a,o as i,c as s,a2 as t}from"./chunks/framework.vLhlLNVn.js";const c=JSON.parse('{"title":"Wie wähle ich Version und Zugriffsweg des Dashboards?","description":"","frontmatter":{"order":3,"adapter":"esphome","editLink":"https://github.com/DrozmotiX/ioBroker.esphome/edit/main/docs/de/02.anleitungen/03.dashboard-nutzen.md"},"headers":[],"relativePath":"de/adapter/esphome/anleitungen/dashboard-nutzen.md","filePath":"de/adapter/esphome/anleitungen/dashboard-nutzen.md","lastUpdated":1795388431000}'),n={name:"de/adapter/esphome/anleitungen/dashboard-nutzen.md"};function r(d,e,o,l,h,u){return i(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="wie-wahle-ich-version-und-zugriffsweg-des-dashboards" tabindex="-1">Wie wähle ich Version und Zugriffsweg des Dashboards? <a class="header-anchor" href="#wie-wahle-ich-version-und-zugriffsweg-des-dashboards" aria-label="Permalink to &quot;Wie wähle ich Version und Zugriffsweg des Dashboards?&quot;">​</a></h1><p><a id="choose-update-esphome-dashboard-version"></a></p><h2 id="wie-wahle-oder-aktualisiere-ich-die-esphome-dashboard-version-auch-altere" tabindex="-1">Wie wähle oder aktualisiere ich die ESPHome-Dashboard-Version, auch ältere? <a class="header-anchor" href="#wie-wahle-oder-aktualisiere-ich-die-esphome-dashboard-version-auch-altere" aria-label="Permalink to &quot;Wie wähle oder aktualisiere ich die ESPHome-Dashboard-Version, auch ältere?&quot;">​</a></h2><p><strong>Kurz:</strong> Du wählst die Version in den Instanz-Einstellungen unter „ESPHome Dashboard-Version“ und passend dazu die „Pillow-Version“. Nach dem Speichern startet die Instanz neu und installiert genau diese Versionen. Ein Update des Adapters brauchst du dafür nicht.</p><p>Voreingestellt sind ESPHome <code>2026.6.5</code> und Pillow <code>12.2.0</code>. Diese Kombination lässt sich zuverlässig installieren. Neuere ESPHome-Versionen ab 2026.7 scheiterten bei vielen Nutzern beim Installieren.</p><h3 id="so-gehst-du-vor" tabindex="-1">So gehst du vor <a class="header-anchor" href="#so-gehst-du-vor" aria-label="Permalink to &quot;So gehst du vor&quot;">​</a></h3><ol><li>Öffne die Instanz-Einstellungen von ESPHome, Reiter „ESPHome-Dashboard“.</li><li>Wähle bei „ESPHome Dashboard-Version“ die gewünschte Version aus der Liste.</li><li>Wähle bei „Pillow-Version“ die Version, die zu dieser ESPHome-Version passt. Welche das ist, siehst du, wenn die Installation scheitert: pip nennt im Log die verlangte Pillow-Version.</li><li>Speichere. Die Instanz startet neu und richtet die Python-Umgebung mit den neuen Versionen ein. Das dauert einige Minuten.</li><li>Im Log steht danach „Starting ESPHome Dashboard“. Unter <code>esphome.0._ESPHomeDashboard.selectedVersion</code> siehst du die verwendete Version, unter <code>esphome.0._ESPHomeDashboard.newestVersion</code> die neueste bei GitHub.</li></ol><h3 id="woher-kommt-die-liste-und-warum-fehlen-altere-versionen" tabindex="-1">Woher kommt die Liste, und warum fehlen ältere Versionen? <a class="header-anchor" href="#woher-kommt-die-liste-und-warum-fehlen-altere-versionen" aria-label="Permalink to &quot;Woher kommt die Liste, und warum fehlen ältere Versionen?&quot;">​</a></h3><p>Die ESPHome-Versionen holt der Adapter beim Start von GitHub. Er liest dabei nur die erste Seite der Release-Liste, also etwa die 30 neuesten Releases, Vorabversionen eingeschlossen. Ältere Versionen stehen deshalb meist nicht in der Liste, und eine eigene Eingabe lässt das Feld nicht zu. Die Pillow-Liste kommt von PyPI und enthält die 20 neuesten stabilen Versionen.</p><p>Ist GitHub beim Start nicht erreichbar, nimmt der Adapter die Liste vom letzten erfolgreichen Abruf und schreibt eine Warnung ins Log: „Unable to retrieve current Dashboard release versions, using cached values“. Die voreingestellten Versionen <code>2026.6.5</code> und <code>12.2.0</code> stehen immer zur Auswahl.</p><h3 id="was-bedeutet-„always-last-available" tabindex="-1">Was bedeutet „Always last available“? <a class="header-anchor" href="#was-bedeutet-„always-last-available" aria-label="Permalink to &quot;Was bedeutet „Always last available“?&quot;">​</a></h3><p>Mit „Always last available“ installiert der Adapter bei jedem Start die neueste Version von GitHub bzw. PyPI. Dein Dashboard wechselt dann ohne dein Zutun auf jedes neue Release, auch auf eines, das sich nicht installieren lässt. Der Adapter warnt deshalb beim Start im Log.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Wähle feste Versionen. Willst du aktualisieren, stell die neue Version gezielt ein und behalte die alte im Kopf, falls du zurück musst.</p></div><p>Stand deine Instanz vor v1.0.0 auf „Always last available“, hat der Adapter sie beim Update einmalig auf <code>2026.6.5</code> und <code>12.2.0</code> umgestellt und das im Log vermerkt. Stellst du danach wieder „Always last available“ ein, bleibt das so.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Meldet das Dashboard selbst, dass ein Update verfügbar ist, betrifft das nur die Anzeige im Dashboard. Welche Version läuft, bestimmt allein die Einstellung im Adapter.</p></div><p><strong>Siehe auch:</strong> <a href="./../fehlerbehebung/dashboard-startet-nicht#dashboard-not-start-pillow-esphome">Warum startet das Dashboard nicht?</a></p><p><a id="use-external-esphome-dashboard-instead"></a></p><h2 id="wie-nutze-ich-ein-externes-esphome-dashboard-statt-des-integrierten" tabindex="-1">Wie nutze ich ein externes ESPHome-Dashboard statt des integrierten? <a class="header-anchor" href="#wie-nutze-ich-ein-externes-esphome-dashboard-statt-des-integrierten" aria-label="Permalink to &quot;Wie nutze ich ein externes ESPHome-Dashboard statt des integrierten?&quot;">​</a></h2><p><em>Dieser Abschnitt wird noch geschrieben.</em></p><p><a id="show-dashboard-admin-tab-using"></a></p><h2 id="wie-zeige-ich-das-dashboard-im-admin-tab-bei-https-an" tabindex="-1">Wie zeige ich das Dashboard im Admin-Tab bei HTTPS an? <a class="header-anchor" href="#wie-zeige-ich-das-dashboard-im-admin-tab-bei-https-an" aria-label="Permalink to &quot;Wie zeige ich das Dashboard im Admin-Tab bei HTTPS an?&quot;">​</a></h2><p><em>Dieser Abschnitt wird noch geschrieben.</em></p>',22)])])}const m=a(n,[["render",r]]);export{c as __pageData,m as default};
